/* ============ P: PROFILES, PRIVATE LAYER & ACCESS, SAFETY ============ */
function profileView(id,r,o={}){
 const me=id==='me';if(me&&r.p.preview)S.ui.profilePreview=r.p.preview;const p=person(id);const ix=(S.ui.ph||{})[id]||0;const t=r.p.t||'about';
 const displayName=me?(p.name||p.nick||L('Ты','You')):pname(id);const posts=(me?S.myPosts.filter(x=>x.status==='published'):allPosts().filter(x=>x.author===id)).sort((a,b)=>b.t-a.t);
 const mutual=isMatch(id),liked=S.likesOut.some(l=>l.p===id),canLike=!me&&(p.dating||p.socialLikes);
 const sh=me?null:shared(id);
 const keys=[p.format&&opt('format',p.format),p.role&&p.role!=='none'&&opt('role',p.role),...(p.dating?(p.seek||[]).slice(0,2).map(s=>opt('seek',s)):[])].filter(Boolean);
 const likeBtn=mutual?`<button class="btn primary" data-act="openChat" data-v="${id}">${I.chat}${L('Написать','Message')}</button>`:liked?`<button class="btn on" data-act="unlikeP" data-v="${id}" aria-pressed="true">${I.heartf}${L('Симпатия','Liked')}</button>`:canLike?`<button class="btn primary" data-act="likeProfile" data-v="${id}">${I.heartf}${L('Нравится','Like')}</button>`:`<button class="btn soft off" title="${L('Не принимает симпатии','Not accepting likes')}">${I.heart}${L('Симпатии выкл.','Likes off')}</button>`;
 const pending=S.reqOut.find(x=>x.p===id&&x.status==='pending');
 const acts=me?`<div class="row g8" style="margin-top:16px"><button class="btn primary" data-go="P02">${I.edit}${L('Редактировать','Edit profile')}</button><button class="btn soft" data-act="shareProfile">${I.share}${L('Поделиться','Share')}</button></div>`
  :`<div class="p-acts">${likeBtn}<button class="btn soft" data-act="follow" data-v="${id}" aria-pressed="${S.follows.has(id)}">${S.follows.has(id)?`${I.check}${L('Подписка','Following')}`:L('Подписаться','Follow')}</button><button class="ibtn" data-act="reqAccess" data-v="${id}" aria-label="${L('Запросить расширенный профиль','Request private profile')}">${pending?I.clock:I.lock}</button></div>`;
 const tabs=tabsRow([['about',L('Профиль','Profile')],['jars',L('Баночки','Jars'),(p.jars||[]).length||''],['posts',L('Публикации','Posts'),posts.length||'']],t,'pTab');
 const orgEvents=allEventIds().filter(e=>EV(e).organizer===id&&!isPast(e)&&!EV(e).cancelled&&EV(e).status!=='review');
 const modOf=Object.keys(COMMUNITIES).filter(c=>COMMUNITIES[c].mods.includes(id));
 let body='';
 if(t==='about')body=`${T(p.bio)?`<p style="margin:4px 0 0;font-size:15.5px;line-height:1.55">${esc(T(p.bio))}</p>`:me?`<button class="alert info" style="width:100%;text-align:left" data-go="P02">${I.edit}<span><b>${L('Добавь пару слов о себе','Add a few words about yourself')}</b>${L('Так людям проще начать разговор','It makes starting a conversation easier')}</span></button>`:''}
  <div class="sec">${L('Кратко','At a glance')}</div><dl class="kv">${[[L('Местоимения','Pronouns'),opt('pron',p.pron)],[L('Гендер','Gender'),(p.gender||[]).map(g=>opt('gender',g)).join(', ')],[L('Ориентация','Orientation'),(p.orient||[]).map(g=>opt('orient',g)).join(', ')],[L('Отношения','Relationships'),opt('format',p.format)],[L('Роль','Role'),p.role&&p.role!=='none'?opt('role',p.role):''],[L('Ищет','Looking for'),p.dating?(p.seek||[]).map(s=>opt('seek',s)).join(', '):''],[L('Языки','Languages'),(p.langs||[]).map(x=>({ru:'русский',en:'English',de:'Deutsch'}[x])).join(', ')]].filter(x=>x[1]).map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')||`<dt>${L('Пока пусто','Empty for now')}</dt><dd></dd>`}</dl>
  ${modOf.length?`<div class="sec">${L('Ведёт сообщества','Runs communities')}</div>${modOf.map((c,i)=>commCard(c,{i})).join('')}`:''}
  ${orgEvents.length?`<div class="sec">${L('Организует','Organising')}</div>${orgEvents.map(e=>eventCard(e,{row:1})).join('<div style="height:8px"></div>')}`:''}
  ${me?'':`<div class="sec">${L('Расширенный профиль','Private profile')}</div>${veilBlock(id)}`}`;
 if(t==='jars')body=(p.jars||[]).length?`<p class="note" style="margin:6px 0 12px">${L('Уровень — как тема откликается сейчас, по шкале от 1 до 5. Границы в публичном профиле не показываются.','Level is how a topic resonates now, from 1 to 5. Limits are never shown on a public profile.')}</p><div class="mini-jars">${jarsHTML(p.jars,{pre:1})}</div>${me?`<button class="btn soft mt12" data-act="toMap">${L('Управлять в «Моей карте»','Manage in My map')}</button>`:''}`:empty('spark',me?L('Ты ещё не открыл(а) ни одного интереса','You haven’t made any interests public'):L('Интересы скрыты','Interests are hidden'),me?L('Интересы публикуются по одному из «Моей карты».','Interests are published one by one from My map.'):L(`${pname(id)} пока не открыл(а) интересы.`,`${pname(id)} hasn’t shared interests yet.`),me?`<button class="btn primary" data-act="toMap">${L('Открыть карту','Open my map')}</button>`:'');
 if(t==='posts')body=posts.length?`<div class="posts">${posts.map((x,i)=>postCard(x,{i})).join('')}</div>`:empty('feed',L('Публикаций нет','No posts yet'),me?L('Твои публикации будут здесь.','Your posts will appear here.'):L(`${pname(id)} пока ничего не публиковал(а).`,`${pname(id)} hasn’t posted yet.`),me?`<button class="btn primary" data-act="create">${L('Создать публикацию','Create a post')}</button>`:'');
 const html=`<header class="bar overlay"><button class="ibtn glass" data-back aria-label="${L('Назад','Back')}">${I.back}</button><span style="flex:1"></span>${me?`<button class="ibtn glass" data-go="P02" aria-label="${L('Редактировать','Edit')}">${I.edit}</button>`:`<button class="ibtn glass" data-act="profileMenu" data-v="${id}" aria-label="${L('Ещё','More')}">${I.more}</button>`}</header>
 <div class="view nodock top0"><div class="wrap">
 ${o.banner||''}
 <div class="hero">${me&&!p.photo?`<div class="plate" style="${PL.rose};position:absolute;inset:0"><span class="pi">${I.me}</span></div>`:me&&p.photo?`<img src="${IMG(p.photo)}" alt="${esc(displayName)}">`:bigPhoto(id,ix)}<div class="pc-bars">${(id==='me'?S.me.photos:[p.photo]).filter(Boolean).map((_,i)=>`<i class="${i===ix?'on':''}"></i>`).join('')}</div><div class="pc-zone l" data-act="pPhoto" data-v="-1"></div><div class="pc-zone r" data-act="pPhoto" data-v="1"></div>
  <div class="pc-info"><h2 class="pc-name">${esc(displayName)}${p.age&&p.dating?`<span>${p.age}</span>`:''}${p.verified?I.verified:''}</h2><div class="pc-who"><span>${esc(whoLine(id))}</span><span>${esc(placeLine(id))}</span>${!me&&p.online?`<span class="on">${L('в сети','online')}</span>`:''}</div>${keys.length?`<div class="pc-keys">${keys.map(k=>`<span>${esc(k)}</span>`).join('')}</div>`:''}</div></div>
 ${acts}
 ${!me&&mutual?`<p class="note center mt8">${L('Вы совпали — можно переписываться','You matched — you can chat')}</p>`:''}
 ${!me?`<button class="why mt12" data-go="P05" data-id="${id}">${venn(sh.few?'?':sh.match.length,{mini:1})}<span class="grow"><b>${esc(sharedSummary(id))}</b><span>${L('Что у вас общего','What you share')}</span></span>${I.chev}</button>`:''}
 <div style="height:14px"></div>${tabs}${body}</div></div>`;if(me)delete S.ui.profilePreview;return html;
}
SC.P01={title:p=>pname(p.id),valid:p=>!!PEOPLE[p.id]&&!isBlocked(p.id),render:(p,r)=>profileView(p.id,r),after:()=>fillJars()};
SC.P03={title:()=>L('Мой профиль','My profile'),render:(p,r)=>profileView('me',r,{banner:''}).replace('<div class="hero">',`<div class="alert info" style="margin:calc(58px + var(--safe-t)) 0 12px">${I.eye}<span><b>${L('Так тебя видят другие','This is how others see you')}</b>${S.me.dating?L('Знакомства включены — в подборке видны возраст и «Ищет».','Dating is on — Discover shows your age and “Looking for”.'):L('Знакомства выключены — возраст и «Ищет» скрыты.','Dating is off — age and “Looking for” are hidden.')}</span></div><div class="hero">`),after:()=>fillJars()};
ACT.pTab=a=>{cur().p.t=a.dataset.v;refresh();};
ACT.pPhoto=a=>{const id=cur().p.id||'me';S.ui.ph=S.ui.ph||{};S.ui.ph[id]=Math.max(0,Math.min((id==='me'?S.me.photos.length:1)-1,(S.ui.ph[id]||0)+(+a.dataset.v)));refresh();};
ACT.toMap=()=>tab('me',{sub:'map'});
ACT.shareProfile=()=>toast(L('Ссылка на профиль скопирована. Без входа она ничего не покажет','Profile link copied. It shows nothing without signing in'),{type:'ok'});
ACT.follow=a=>{const id=a.dataset.v;const on=!S.follows.has(id);on?S.follows.add(id):S.follows.delete(id);
 if(a.classList.contains('btn')&&a.closest('.pc-foot')){a.textContent=on?L('Ты подписан(а)','Following'):L('Подписаться','Follow');}else refresh();
 toast(on?L(`Подписка на ${pname(id)}: посты появятся в «Подписках». Чат это не открывает`,`Following ${pname(id)}: posts appear in Following. This doesn’t open a chat`):L('Ты отписался(ась)','Unfollowed'),{type:on?'ok':''});};
/* R04 — like from a social profile without enrolling in discovery */
ACT.likeProfile=a=>{const id=a.dataset.v;
 if(!S.me.dating&&!S.me.socialLikes){toast(L('Симпатии выключены. Включи их в настройках приватности.','Likes are off. Enable them in privacy settings.'),{type:'warn',action:{label:L('Настройки','Settings'),fn:()=>go('K04')}});return;}const doLike=()=>run(a,()=>{likePerson(id,'profile');refresh();},{ms:300});
 if(S.me.dating||S.ui.r04seen)return doLike();
 sheet(()=>({title:L('Симпатия из профиля','Like from a profile'),lead:`<span class="ico l">${I.heart}</span>`,body:`<div class="fact"><i class="g">${I.check}</i><span>${L(`Если ${pname(id)} ответит взаимностью, откроется личный чат.`,`If ${pname(id)} likes you back, a private chat opens.`)}</span></div><div class="fact"><i class="g">${I.check}</i><span>${L('Твой профиль не появится в подборке знакомств — они у тебя выключены.','Your profile won’t appear in Discover — your dating is off.')}</span></div><div class="fact"><i class="v">${I.info}</i><span>${L('Симпатию можно отменить, человек об этом не узнает.','You can withdraw the like; they won’t be told.')}</span></div>`,foot:`<button class="btn primary" data-act="r04ok" data-v="${id}">${I.heartf}${L('Отправить симпатию','Send like')}</button>`}));};
ACT.r04ok=a=>{S.ui.r04seen=1;closeSheet(true);run(null,()=>{likePerson(a.dataset.v,'profile');refresh();},{ms:300});};
ACT.unlikeP=a=>ACT.unlike(a);

/* profile menu: share / report / block */
ACT.profileMenu=a=>{const id=a.dataset.v;sheet(()=>({title:pname(id),body:`<div class="card list">${linkRow({act:'shareProfile',icon:'link',title:L('Скопировать ссылку','Copy link'),noChev:1})}${S.likesOut.some(l=>l.p===id)?linkRow({act:'unlike',v:id,icon:'heart',title:L('Отменить симпатию','Withdraw like'),noChev:1}):''}${linkRow({act:'report',v:'person',icon:'flag',cls:'danger',title:L('Пожаловаться','Report'),noChev:1})}${linkRow({act:'block',v:id,icon:'block',cls:'danger',title:L('Заблокировать','Block'),sub:L('Прекратит контакт и все доступы','Ends contact and all access'),noChev:1})}</div>`}));};
/* S02 — report */
ACT.report=a=>{const kind=a.dataset.v||'person';S.ui.rp={why:'',block:kind==='person'};closeSheet(true);
 sheet(()=>{const o=S.ui.rp;return{title:L('Пожаловаться','Report'),body:`<p class="lead">${L('Жалобу рассмотрит модератор. Человек не узнает, кто пожаловался.','A moderator reviews the report. The person won’t know who reported.')}</p>${[['threat',L('Угрозы или шантаж','Threats or blackmail')],['private',L('Чужие приватные материалы','Someone else’s private content')],['minor',L('Похоже на несовершеннолетнего','Looks underage')],['spam',L('Спам или мошенничество','Spam or scam')],['other',L('Другое','Something else')]].map(([k,l])=>`<button class="radio ${o.why===k?'on':''}" data-act="rpWhy" data-v="${k}"><i></i><span class="tx">${l}</span></button>`).join('')}
 <label class="field mt16"><span>${L('Подробности','Details')}<i>${L('необязательно','optional')}</i></span><textarea class="inp" id="rpText" rows="3" maxlength="500"></textarea></label>${kind==='person'?`<div class="card list">${toggleRow('rpBlock',L('Также заблокировать','Also block'),L('Сразу прекратить контакт','End contact right away'),o.block)}</div>`:''}`,
 foot:`<button class="btn danger" data-act="rpSend" data-v="${kind}">${L('Отправить жалобу','Send report')}</button>`};});};
ACT.rpWhy=a=>{S.ui.rp.why=a.dataset.v;resheet();};
ACT.rpBlock=()=>{S.ui.rp.block=!S.ui.rp.block;resheet();};
ACT.rpSend=a=>{if(!S.ui.rp.why){toast(L('Выбери причину жалобы','Choose a reason'),{type:'err'});$('#sheet .radio')?.classList.add('shake');return;}
 const id=cur().p.id;run(a,()=>{closeSheet();if(S.ui.rp.block&&id&&PEOPLE[id])doBlock(id);},{ok:L('Жалоба отправлена. Сообщим о решении в уведомлениях','Report sent. We’ll notify you of the decision')});};
ACT.block=a=>{const id=a.dataset.v;closeSheet(true);ask({icon:'block',tone:'l',title:L(`Заблокировать ${pname(id)}?`,`Block ${pname(id)}?`),text:L('Симпатии, чат и выданные доступы прекратятся сразу. Человек не получит уведомление. Разблокировка не вернёт доступы.','Likes, chat and any access you shared end immediately. They won’t be notified. Unblocking doesn’t restore access.'),ok:L('Заблокировать','Block'),danger:true}).then(ok=>{if(ok)run(null,()=>doBlock(id),{ok:L('Заблокировано','Blocked')});});};
function doBlock(id){S.reqOut=S.reqOut.filter(x=>x.p!==id);S.reqIn=S.reqIn.filter(x=>x.p!==id);S.notifs=S.notifs.filter(x=>x.p!==id);S.likesIn=S.likesIn.filter(x=>x.p!==id);S.blocked.unshift({p:id,t:Date.now()});S.matches=S.matches.filter(m=>m.p!==id);S.likesOut=S.likesOut.filter(l=>l.p!==id);S.sharedByMe=S.sharedByMe.filter(x=>x.p!==id);S.follows.delete(id);delete S.threads[id];
 const st=stack();while(st.length>1&&st[st.length-1].p&&st[st.length-1].p.id===id)st.pop();render('back');}

/* P05 — shared interests: categories, no universal score */
SC.P05={title:()=>L('Что у вас общего','Shared interests'),valid:p=>!!PEOPLE[p.id]&&!isBlocked(p.id),render:(p)=>{const id=p.id;const s=shared(id);const g=S.reqOut.find(x=>x.p===id&&['partial','granted'].includes(x.status)&&(x.until===null||x.until>Date.now()));
 return `${bar(L('Что у вас общего','Shared interests'),{back:1,sm:1})}<div class="view nodock"><div class="wrap">
 ${venn(s.few?'?':s.match.length,{pre:1})}<p class="center note" style="margin-top:6px">${L('Ты и','You and')} ${esc(pname(id))}</p>
 <div class="card mt16">
  <div class="cat"><span class="ico g">${I.check}</span><div class="tx"><b>${L('Совпадает','In common')}</b>${s.match.length?`<div class="chips">${s.match.map(m=>`<span class="chip hit">${esc(topic(m))}</span>`).join('')}</div>`:`<p class="note">${L('Пока нет общих открытых тем','No shared public topics yet')}</p>`}</div></div>
  <div class="cat"><span class="ico v">${I.couple}</span><div class="tx"><b>${L('Дополняется','Complements')}</b>${s.complement.length?s.complement.map(c=>`<p class="note" style="color:var(--ink);margin-top:4px">${esc(c)}</p>`).join(''):`<p class="note">${L('Роли не указаны','Roles not specified')}</p>`}</div></div>
  <div class="cat"><span class="ico a">${I.warn}</span><div class="tx"><b>${L('Стоит обсудить','Worth discussing')}</b>${s.discuss.length?s.discuss.map(c=>`<p class="note" style="color:var(--ink);margin-top:4px">${esc(c)}</p>`).join(''):`<p class="note">${L('Явных различий не видно','No obvious differences')}</p>`}</div></div>
  ${s.few?`<div class="cat"><span class="ico">${I.info}</span><div class="tx"><b>${L('Мало данных','Not enough data')}</b><p class="note">${L('Пока мало общего контекста — это не оценка человека.','Not much shared context yet — this isn’t a judgement of the person.')}</p></div></div>`:''}
 </div>
 <div class="alert mt12">${I.lock}<span>${L('Сравниваем только то, что вы оба открыли: публичные интересы, формат и роль.','We compare only what you both made visible: public interests, format and role.')} ${g?L('Расширенный профиль доступен отдельно и не участвует в публичном объяснении.','The private profile is available separately and excluded from the public explanation.'):L('Скрытые темы и границы не участвуют и не раскрываются.','Hidden topics and limits are never used or revealed.')}</span></div>
 ${S.me.jars.filter(j=>j.vis==='public').length<3?`<button class="btn soft mt12" data-act="toMap">${L('Открыть больше своих интересов','Make more of your interests public')}</button>`:''}
 </div></div>`;},after:()=>playVenn()};

/* P06 — request private access: categories, quota, no message, no chat */
ACT.reqAccess=a=>{const id=a.dataset.v||cur().p.id;if(!needAge(()=>ACT.reqAccess({dataset:{v:id}})))return;
 const pend=S.reqOut.find(x=>x.p===id&&x.status==='pending');
 if(pend){sheet(()=>({title:L('Запрос уже отправлен','Request already sent'),lead:`<span class="ico a">${I.clock}</span>`,body:`<p class="lead">${L(`${pname(id)} ещё не ответил(а). Ответ придёт в уведомления.`,`${pname(id)} hasn’t answered yet. You’ll be notified.`)}</p><div class="card list">${linkRow({icon:'lock',title:pend.scopes.map(s=>T(REQ_SCOPES.find(x=>x[0]===s)[1])).join(', '),sub:L('Отправлен','Sent')+' '+F.rel(pend.t),noChev:1})}</div>`,foot:`<button class="btn soft" data-act="cancelReq" data-v="${pend.id}">${L('Отменить запрос','Cancel request')}</button><button class="btn text" data-act="toAccess" data-v="out">${L('Все мои запросы','All my requests')}</button>`}));return;}
 const dec=S.reqOut.find(x=>x.p===id&&x.status==='declined'&&Date.now()-x.t<7*DAY);
 if(dec){toast(L('Повторный запрос этому человеку можно отправить через 7 дней после отказа','You can ask this person again 7 days after a decline'),{type:'warn'});return;}
 if(C.quotaLeft()<=0){limitSheet();return;}
 const scopes=id==='mia'?REQ_SCOPES:REQ_SCOPES.filter(s=>s[0]!=='album');S.ui.rq={id,sel:['info']};
 sheet(()=>{const o=S.ui.rq;const left=C.quotaLeft(),max=S.me.premium?15:S.quota.max;return{title:L('Запросить расширенный профиль','Request private profile'),body:`<p class="lead">${L(`Отметь, что хочешь увидеть. Что открыть — решает ${pname(id)}.`,`Choose what you’d like to see. ${pname(id)} decides what to share.`)}</p>
 ${chipGroup(scopes.map(([k,l])=>[k,T(l)]),o.sel,'rqPick')}
 <div class="sec">${L('Осталось запросов сегодня','Requests left today')}<b style="color:var(--ink)">${left} ${L('из','of')} ${max}</b></div><div class="quota">${Array.from({length:Math.min(max,15)},(_,i)=>`<i class="${i<left?'':'off'}"></i>`).join('')}</div>
 <div class="alert mt16">${I.info}<span>${L('Запрос не отправляет сообщение и не открывает чат. Можно открыть меньше или отказать без объяснения.','A request sends no message and doesn’t open a chat. They can share less or decline without explanation.')}</span></div>`,
 foot:`<button class="btn primary ${o.sel.length?'':'off'}" data-act="rqSend">${L('Отправить запрос','Send request')}</button>`};});};
ACT.rqPick=a=>{const s=S.ui.rq.sel;const i=s.indexOf(a.dataset.v);i<0?s.push(a.dataset.v):s.splice(i,1);resheet();};
ACT.rqSend=a=>{const o=S.ui.rq;if(!o.sel.length){toast(L('Выбери хотя бы один раздел','Pick at least one section'),{type:'err'});return;}
 run(a,()=>{S.reqOut.unshift({id:'o'+Date.now(),p:o.id,scopes:[...o.sel],t:Date.now(),status:'pending'});S.quota.used++;closeSheet();if(['P01','D03','H02','H03'].includes(cur().id))cur().id==='D03'?deckRender():refresh();},{ok:L(`Запрос отправлен. Осталось ${C.quotaLeft()}`,`Request sent. ${C.quotaLeft()} left`)});};
/* B02 — the single paywall moment: quota of new outgoing requests */
function limitSheet(){sheet(()=>({title:L('Запросы на сегодня закончились','No requests left today'),lead:`<span class="ico a">${I.timer}</span>`,body:`<p class="lead">${L('Бесплатно — 3 новых запроса за 24 часа. Ближайший освободится через 5 ч.','Free gives 3 new requests per 24 hours. The next one frees up in 5 h.')}</p>
 <div class="quota"><i class="off"></i><i class="off"></i><i class="off"></i></div>
 <div class="card flat mt16"><b>Premium</b><p class="note">${L('15 запросов в сутки. Это не покупает согласие: человек всё равно решает сам.','15 requests a day. It doesn’t buy consent — people still decide for themselves.')}</p></div>
 <p class="note mt12">${L('Отвечать на запросы, отзывать доступы и скрываться из подборки — всегда бесплатно.','Answering requests, revoking access and hiding from Discover are always free.')}</p>`,
 foot:`<button class="btn primary" data-go="B01">${L('Посмотреть Premium','See Premium')}</button><button class="btn soft" data-act="closeSheet">${L('Подожду до завтра','I’ll wait')}</button>`}));}
ACT.cancelReq=a=>{const x=S.reqOut.find(y=>y.id===a.dataset.v);run(a,()=>{x.status='cancelled';closeSheet();refresh();},{ok:L('Запрос отменён. Попытка не возвращается','Request cancelled. The attempt isn’t refunded')});};
ACT.toAccess=a=>{closeSheet(true);go('P07',{tab:a.dataset.v||'in'});};

/* P07 — access center: received / sent / shared with me / shared by me */
const SCOPE_TXT=arr=>arr.map(s=>T(REQ_SCOPES.find(x=>x[0]===s)[1])).join(', ');
const REQ_STATUS=()=>({pending:['wait',L('ждёт ответа','pending')],partial:['ok',L('открыт частично','partly shared')],granted:['ok',L('открыт','shared')],declined:['bad',L('без ответа','no answer')],expired:['',L('истёк','expired')],cancelled:['',L('отменён','cancelled')]});
SC.P07={title:()=>L('Доступы','Access'),render:(p)=>{S.reqOut.forEach(x=>{if(['partial','granted'].includes(x.status)&&x.until!==null&&x.until<=Date.now())x.status='expired';});S.sharedByMe=S.sharedByMe.filter(x=>(x.until===null||x.until>Date.now())&&!isBlocked(x.p));const t=p.tab||'in';
 const inc=S.reqIn.filter(r=>!isBlocked(r.p)),out=S.reqOut.filter(r=>!isBlocked(r.p)),withMe=S.reqOut.filter(r=>['partial','granted'].includes(r.status)&&(r.until===null||r.until>Date.now())),byMe=S.sharedByMe;
 const tabs=tabsRow([['in',L('Ко мне','Received'),C.reqIn()||''],['out',L('Мои запросы','Sent'),out.filter(x=>x.status==='pending').length||''],['withme',L('Открыто мне','Shared with me')],['byme',L('Кому открыто','Shared by me')]],t,'p7tab');
 let body='';
 if(t==='in')body=`<p class="note" style="margin:0 0 12px">${L('Запросы к тебе бесплатны. Ты решаешь, что открыть и на какой срок. Отказ без объяснений.','Requests to you are free. You decide what to share and for how long. No explanation needed to decline.')}</p>${inc.length?inc.map(r=>`<div class="card" style="margin-bottom:10px"><div class="row">${av(r.p,'')}<button class="grow" style="text-align:left" data-go="P01" data-id="${r.p}"><b style="font-size:16px">${esc(pname(r.p))}${person(r.p).age?', '+person(r.p).age:''}</b><div class="note">${F.rel(r.t)} · ${esc(sharedSummary(r.p))}</div></button></div><div class="chips mt12">${r.scopes.map(s=>`<span class="pill">${esc(T(REQ_SCOPES.find(x=>x[0]===s)[1]))}</span>`).join('')}</div>
  ${r.status==='new'?`<div class="row g8 mt12"><button class="btn md primary" data-act="grant" data-v="${r.id}">${L('Открыть…','Share…')}</button><button class="btn md soft" data-act="decline" data-v="${r.id}">${L('Отказать','Decline')}</button></div>`:`<div class="row mt12" style="gap:8px;font-size:13.5px;font-weight:600;color:${r.status==='open'?'var(--mint)':'var(--mute)'}">${r.status==='open'?I.check:I.x}${r.status==='open'?L(`Открыто: ${SCOPE_TXT(r.granted)} · ${F.left(r.until)}`,`Shared: ${SCOPE_TXT(r.granted)} · ${F.left(r.until)}`):L('Отказано. Человек видит нейтральное «без ответа»','Declined. They see a neutral “no answer”')}</div>`}</div>`).join(''):empty('lock',L('Запросов нет','No requests'),L('Когда кто-то попросит открыть расширенный профиль, запрос появится здесь.','When someone asks to see your private profile, it appears here.'))}
  <div class="card list mt16">${linkRow({go:'P04',icon:'gear',title:L('Кто может запрашивать','Who can ask'),val:{all:L('все','everyone'),matches:L('совпадения','matches'),none:L('никто','nobody')}[S.me.requestsFrom]})}</div>`;
 if(t==='out'){const only=p.f==='pending';const list=out.filter(r=>!only||r.status==='pending');body=`<div class="row" style="justify-content:space-between;margin-bottom:10px"><span class="note">${L('Сегодня осталось','Left today')} <b>${C.quotaLeft()} ${L('из','of')} ${S.me.premium?15:S.quota.max}</b></span><button class="chip filter ${only?'on':''}" data-act="p7f">${L('Ждут ответа','Pending')}</button></div>
  ${list.length?`<div class="card list">${list.map(r=>{const [c,l]=REQ_STATUS()[r.status];return `<div class="rqrow"><button class="top" style="width:100%;text-align:left" data-go="P01" data-id="${r.p}">${av(r.p,'')}<span class="grow"><b>${esc(pname(r.p))} <span class="pill ${c}">${l}</span></b><small>${L('Просил(а)','Asked for')}: ${esc(SCOPE_TXT(r.scopes))} · ${F.rel(r.t)}</small>${r.status==='partial'?`<small>${L('Открыто','Shared')}: ${esc(SCOPE_TXT(r.granted))} · ${F.left(r.until)}</small>`:''}</span></button>${r.status==='pending'?`<div class="acts3"><button class="btn text auto" data-act="cancelReq" data-v="${r.id}">${L('Отменить запрос','Cancel request')}</button></div>`:['partial','granted'].includes(r.status)?`<div class="acts3"><button class="btn text auto" data-go="P08" data-id="${r.p}">${L('Смотреть открытое','View shared')}</button></div>`:''}</div>`;}).join('')}</div>`:empty('send',only?L('Ничего не ждёт ответа','Nothing pending'):L('Ты ещё ничего не запрашивал(а)','You haven’t asked for anything yet'),L('Запросить доступ можно в профиле человека или в подборке.','You can request access on a profile or in Discover.'))}
  <p class="note mt12">${L('Отказ показывается как «без ответа». Повторный запрос тому же человеку — не раньше чем через 7 дней.','A decline shows as “no answer”. You can ask the same person again after 7 days.')}</p>`;}
 if(t==='withme')body=withMe.length?`<div class="card list">${withMe.map(r=>linkRow({go:'P08',p:{id:r.p},av:av(r.p,''),title:pname(r.p),sub:`${SCOPE_TXT(r.granted)} · ${F.left(r.until)}`})).join('')}</div>`:empty('unlock',L('Пока никто не открыл','Nothing shared with you yet'),L('Здесь появятся расширенные профили, которые тебе открыли.','Private profiles shared with you appear here.'));
 if(t==='byme')body=byMe.length?byMe.map(x=>`<div class="card" style="margin-bottom:10px"><div class="row">${av(x.p,'')}<div class="grow"><b>${esc(pname(x.p))}</b><div class="note">${esc(SCOPE_TXT(x.scopes))}</div></div><span class="pill">${x.until?F.left(x.until):L('без срока','no limit')}</span></div><div class="row g8 mt12"><button class="btn md soft" data-act="narrow" data-v="${x.p}">${L('Изменить','Change')}</button><button class="btn md danger" data-act="revoke" data-v="${x.p}">${L('Отозвать','Revoke')}</button></div></div>`).join(''):empty('lock',L('Ты никому не открывал(а) доступ','You haven’t shared with anyone'),L('Открыть можно, ответив на запрос.','You can share by answering a request.'));
 return `${bar(L('Доступы','Access'),{back:1,sm:1})}<div class="view nodock"><div class="wrap">${tabs}${body}</div></div>`;}};
ACT.p7tab=a=>setP('tab',a.dataset.v);
ACT.p7f=()=>setP('f',cur().p.f==='pending'?'':'pending');
/* P09 — review an incoming request: choose less, set a term, preview; no chat toggle */
ACT.grant=a=>{const r=S.reqIn.find(x=>x.id===a.dataset.v);S.ui.gr={id:r.id,sel:[...r.scopes],term:'7'};
 sheet(()=>{const o=S.ui.gr;return{title:L(`Что открыть ${pname(r.p)}`,`What to share with ${pname(r.p)}`),body:`<p class="lead">${L('Просит','Asks for')}: ${esc(SCOPE_TXT(r.scopes))}. ${L('Можно открыть меньше.','You can share less.')}</p>
 ${chipGroup(r.scopes.map(s=>[s,T(REQ_SCOPES.find(x=>x[0]===s)[1])]),o.sel,'grPick')}
 <div class="sec">${L('Срок','Duration')}</div>${seg([['1',L('24 часа','24 hours')],['7',L('7 дней','7 days')],['0',L('Без срока','No limit')]],o.term,'grTerm','sm')}
 <div class="sec">${L(`Что увидит ${pname(r.p)}`,`What ${pname(r.p)} will see`)}</div><div class="card list">${o.sel.length?o.sel.map(s=>`<div class="li"><span class="ico g">${I.unlock}</span><span class="tx"><b>${esc(T(REQ_SCOPES.find(x=>x[0]===s)[1]))}</b><small>${s==='info'?L('Темы с видимостью «по разрешению», включая границы','Topics marked “by permission”, including limits'):s==='photos'?L('3 фото с персональным водяным знаком','3 photos with a personal watermark'):L('Только текущее содержимое; новое — отдельным решением','Current content only; new items need a new decision')}</small></span></div>`).join(''):`<p class="note" style="padding:12px 0">${L('Ничего не выбрано','Nothing selected')}</p>`}</div>
 <p class="note mt12">${L('Доступ не открывает чат. Отозвать можно в любой момент — у человека всё пропадёт сразу.','Access doesn’t open a chat. Revoke any time — it disappears for them at once.')}</p>`,
 foot:`<button class="btn primary ${o.sel.length?'':'off'}" data-act="grOk">${I.unlock}${L('Открыть доступ','Share access')}</button>`};});};
ACT.grPick=a=>{const s=S.ui.gr.sel;const i=s.indexOf(a.dataset.v);i<0?s.push(a.dataset.v):s.splice(i,1);resheet();};
ACT.grTerm=a=>{S.ui.gr.term=a.dataset.v;resheet();};
ACT.grOk=a=>{const o=S.ui.gr;const r=S.reqIn.find(x=>x.id===o.id);const until=o.term==='0'?null:Date.now()+(+o.term)*DAY;
 run(a,()=>{r.status='open';r.granted=[...o.sel];r.until=until;S.sharedByMe.unshift({p:r.p,scopes:[...o.sel],until,t:Date.now()});closeSheet();refresh();},{ok:L(`Открыто ${pname(r.p)}`,`Shared with ${pname(r.p)}`)});};
ACT.decline=a=>{const r=S.reqIn.find(x=>x.id===a.dataset.v);run(a,()=>{r.status='no';refresh();},{ok:L('Отказано. Человек увидит «без ответа»','Declined. They’ll see “no answer”'),undo:()=>{r.status='new';refresh();}});};
/* P11 — revoke */
ACT.revoke=a=>{const id=a.dataset.v;ask({icon:'lock',tone:'l',title:L(`Отозвать доступ у ${pname(id)}?`,`Revoke access for ${pname(id)}?`),text:L('Новые просмотры прекратятся сразу. То, что человек уже видел или сохранил вне FetUre, отозвать нельзя. Чат и симпатия не меняются.','New views stop immediately. What they already saw or saved outside FetUre can’t be recalled. Chat and likes stay as they are.'),ok:L('Отозвать','Revoke'),danger:true}).then(ok=>{if(!ok)return;run(null,()=>{S.sharedByMe=S.sharedByMe.filter(x=>x.p!==id);const r=S.reqIn.find(x=>x.p===id&&x.status==='open');if(r)r.status='no';refresh();},{ok:L('Доступ отозван','Access revoked')});});};
ACT.narrow=a=>{const x=S.sharedByMe.find(y=>y.p===a.dataset.v);S.ui.nw={p:x.p,sel:[...x.scopes]};sheet(()=>({title:L('Изменить доступ','Change access'),body:`<p class="lead">${L('Убери то, что больше не хочешь показывать.','Remove what you no longer want to share.')}</p>${chipGroup(x.scopes.map(s=>[s,T(REQ_SCOPES.find(y=>y[0]===s)[1])]),S.ui.nw.sel,'nwPick')}`,foot:`<button class="btn primary" data-act="nwOk">${L('Сохранить','Save')}</button>`}));};
ACT.nwPick=a=>{const s=S.ui.nw.sel;const i=s.indexOf(a.dataset.v);i<0?s.push(a.dataset.v):s.splice(i,1);resheet();};
ACT.nwOk=a=>{const o=S.ui.nw;if(!o.sel.length){closeSheet(true);ACT.revoke({dataset:{v:o.p}});return;}run(a,()=>{S.sharedByMe.find(y=>y.p===o.p).scopes=[...o.sel];S.reqIn.filter(y=>y.p===o.p&&y.status==='open').forEach(y=>y.granted=[...o.sel]);closeSheet();refresh();},{ok:L('Доступ изменён','Access updated')});};

/* P08 — private profile shared with me */
SC.P08={title:p=>L('Расширенный профиль','Private profile'),valid:p=>!!PEOPLE[p.id]&&!isBlocked(p.id)&&!!S.reqOut.find(x=>x.p===p.id&&['partial','granted'].includes(x.status)&&(x.until===null||x.until>Date.now())),render:(p)=>{const id=p.id;const g=S.reqOut.find(x=>x.p===id&&['partial','granted'].includes(x.status)&&(x.until===null||x.until>Date.now()));const P0=person(id);
 return `${bar(L(`Расширенный профиль ${pname(id)}`,`${pname(id)}’s private profile`),{back:1,sm:1})}<div class="view nodock"><div class="wrap">
 <div class="granted">${I.unlock}<div><b>${L(`${pname(id)} открыл(а) тебе доступ`,`${pname(id)} shared this with you`)}</b><span>${esc(SCOPE_TXT(g.granted))} · ${F.left(g.until)}</span></div></div>
 ${g.granted.includes('info')?`<div class="sec">${L('Желания и статусы','Wishes and status')}</div><div class="card list">${[[topic('shibari'),L('практикую, принимающая роль','practising, receiving role'),'ok'],[topic('sensory'),L('практикую','practising'),'ok'],[topic('temperature'),L('хочу попробовать','want to try'),'wait'],[topic('roleplay'),L('фантазия','fantasy'),''],[topic('aftercare'),L('обязательно','essential'),'hot']].map(([n,v,c])=>`<div class="stat-row"><span>${n}</span><span class="pill ${c}">${v}</span></div>`).join('')}</div>
 <div class="sec">${L('Границы','Limits')}</div><div class="card"><div class="fact"><i class="a">${I.block}</i><span><b>${L('Жёсткая','Hard')}:</b> ${L('публичность и съёмка без согласия','public exposure and filming without consent')}</span></div><div class="fact"><i class="a">${I.warn}</i><span><b>${L('Обсуждать','To discuss')}:</b> ${L('боль — только после долгого знакомства','pain — only after knowing each other well')}</span></div><div class="fact"><i class="g">${I.check}</i><span>${L('Стоп-слово и проверка состояния обязательны','Safeword and check-ins are essential')}</span></div></div>`:''}
 ${g.granted.includes('album')||g.granted.includes('photos')?`<div class="sec">${g.granted.includes('album')?L('Альбом «Лето»','Album “Summer”'):L('Приватные фото','Private photos')}<span class="note" style="font-weight:500">${g.granted.includes('album')?L('6 фото','6 photos'):L('3 фото','3 photos')}</span></div><div class="album">${(g.granted.includes('album')?[0,1,2,1,2,0]:[0,1,2]).map((v,k)=>`<div class="ph-wrap">${P0.photo?`<img src="${IMG(P0.photo)}" alt="" style="filter:hue-rotate(${k*14}deg) saturate(1.1);transform:scale(${1+k*.08})">`:plate('rose')}<span class="wm">${esc(S.me.nick)}</span></div>`).join('')}</div>`:''}
 <p class="note mt12">${L('Фото с персональным водяным знаком. Мы не можем полностью запретить скриншоты — уважай доверие. Доступ могут отозвать в любой момент.','Photos carry a personal watermark. We can’t fully prevent screenshots — respect the trust. Access can be revoked at any time.')}</p>
 </div></div>`;}};

/* P02 — edit my profile: one source of truth for every screen */
SC.P02={title:()=>L('Редактировать профиль','Edit profile'),render:(p,r)=>{const m=S.me;
 if(!r.init){r.init=1;Object.assign(r.f,{name:m.name,nick:m.nick,bio:T(m.bio),city:m.city||''});r.photos=[...m.photos];r.pron=m.pron;r.gender=[...m.gender];r.orient=[...m.orient];r.format=m.format;r.role=m.role;r.langs=[...m.langs];r.vis={...PUBLIC_VIS,...m.vis};}
 const visBtn=k=>`<button class="pill ${r.vis[k]==='public'?'ok':r.vis[k]==='granted'?'v':''}" data-act="visCycle" data-v="${k}">${r.vis[k]==='public'?I.globe:r.vis[k]==='granted'?I.lock:I.eyeoff}${{public:L('всем','everyone'),granted:L('по доступу','by access'),only:L('только я','only me')}[r.vis[k]]}</button>`;
 return `${bar(L('Профиль','Profile'),{back:1,sm:1,actions:`<button class="btn text auto" data-act="previewDraft">${L('Как видят','Preview')}</button>`})}<div class="view nodock cta1"><div class="wrap">
 <div class="sec">${L('Фото','Photos')}<span class="note" style="font-weight:500">${L('необязательно · до 6','optional · up to 6')}</span></div>
 <div class="edit-ph">${r.photos.map((ph,i)=>`<div><img src="${IMG(ph)}" alt="">${i===0?`<span class="mainph">${L('главное','main')}</span>`:''}<button class="rm" data-act="phRm" data-v="${i}" aria-label="${L('Удалить фото','Remove photo')}">${I.close}</button></div>`).join('')}${r.photos.length<6?`<button data-act="phAdd" aria-label="${L('Добавить фото','Add photo')}">${I.camera}</button>`:''}</div>
 <p class="note mt8">${L('Фото проходят проверку. Документы для проверки возраста сюда не загружаются.','Photos are reviewed. Age-check documents are never uploaded here.')}</p>
 <div style="height:16px"></div>${field({name:'name',label:L('Имя','Name'),ph:'Alex',max:30})}
 ${field({name:'nick',label:L('Ник','Nickname'),icon:'at',attrs:'autocapitalize="off" spellcheck="false"',hint:L('Ник — часть аккаунта, отдельного «ника для знакомств» нет.','Your nickname belongs to your account — there’s no separate dating nickname.')})}
 ${field({name:'bio',label:L('О себе','About you'),textarea:1,max:500,ph:L('Пара фраз о том, что для тебя важно','A few lines about what matters to you'),attrs:'rows="4"'})}
 <label class="field"><span>${L('Город','City')}</span><select class="inp" name="city" data-ch="fsel"><option value="">${L('Не показывать','Don’t show')}</option>${['berlin','hamburg','moscow'].map(c=>`<option value="${c}" ${r.f.city===c?'selected':''}>${city(c)}</option>`).join('')}</select></label>
 <div class="field"><span class="flabel">${L('Местоимения','Pronouns')}</span>${chipGroup(optItems('pron'),[r.pron],'peOne',{k:'pron'})}</div>
 ${[['gender',L('Гендер','Gender'),1],['orient',L('Ориентация','Orientation'),1],['format',L('Формат отношений','Relationship format'),0],['role',L('Роль','Role'),0]].map(([k,l,multi])=>`<div class="field"><span class="flabel">${l}${visBtn(k)}</span>${chipGroup(optItems(k),multi?r[k]:[r[k]],multi?'peMulti':'peOne',{k})}</div>`).join('')}
 <div class="field"><span class="flabel">${L('Языки','Languages')}</span>${chipGroup([['ru','русский'],['en','English'],['de','Deutsch']],r.langs,'peMulti',{k:'langs'})}</div>
 <div class="card list">${linkRow({go:'P04',icon:'lock',tone:'v',title:L('Расширенный профиль','Private profile'),sub:L('Разделы, которые открываются по запросу','Sections shared on request')})}${linkRow({act:'toMap',icon:'spark',tone:'l',title:L('Интересы','Interests'),sub:L('Управляются в «Моей карте»','Managed in My map')})}</div>
 </div></div><div class="ctabar"><div class="wrap"><button class="btn primary" data-act="peSave">${L('Сохранить','Save')}</button></div></div>`;}};
ACT.visCycle=a=>{const r=cur();const k=a.dataset.v;const order=['public','granted','only'];r.vis[k]=order[(order.indexOf(r.vis[k])+1)%3];r.dirty=true;refresh();toast({public:L('Видно всем участникам','Visible to all members'),granted:L('Только тем, кому ты открыл(а) доступ','Only people you’ve shared access with'),only:L('Видишь только ты','Only you can see it')}[r.vis[k]]);};
ACT.peOne=a=>{const r=cur();r[a.dataset.k]=r[a.dataset.k]===a.dataset.v?null:a.dataset.v;r.dirty=true;refresh();};
ACT.peMulti=a=>{const r=cur();const arr=r[a.dataset.k];const i=arr.indexOf(a.dataset.v);i<0?arr.push(a.dataset.v):arr.splice(i,1);r.dirty=true;refresh();};
ACT.phAdd=a=>{const r=cur();run(a,()=>{const pool=[8,1,3,5,7,9].filter(x=>!r.photos.includes(x));r.photos.push(pool[0]||8);r.dirty=true;refresh();},{ms:700,ok:L('Фото загружено и отправлено на проверку','Photo uploaded and sent for review')});};
ACT.phRm=a=>{const r=cur();r.photos.splice(+a.dataset.v,1);r.dirty=true;refresh();};
ACT.peSave=a=>{const r=cur();r.err={};const nk=fv('nick').trim();const ne=nk.toLowerCase()===S.me.nick.toLowerCase()?'':V.nick(nk);if(ne)r.err.nick=ne;if(fv('bio').length>500)r.err.bio=L('Максимум 500 символов','500 characters max');if(fv('name').length>30)r.err.name=L('Максимум 30 символов','30 characters max');
 if(Object.keys(r.err).length){refresh();shakeFirstErr();toast(L('Проверь отмеченные поля','Check the highlighted fields'),{type:'err'});return;}
 run(a,()=>{Object.assign(S.me,{name:fv('name').trim(),nick:nk,bio:{ru:fv('bio'),en:fv('bio')},city:r.f.city||null,photos:[...r.photos],photo:r.photos[0]||null,pron:r.pron,gender:r.gender,orient:r.orient,format:r.format,role:r.role,langs:[...r.langs],vis:{...r.vis}});r.dirty=false;back();},{ok:L('Профиль обновлён — изменения видны везде','Profile updated — changes show everywhere')});};

/* P04 — private sections */
SC.P04={title:()=>L('Расширенный профиль','Private profile'),render:()=>`${bar(L('Расширенный профиль','Private profile'),{back:1,sm:1})}<div class="view nodock"><div class="wrap">
 <p class="lead">${L('Эти разделы никто не видит, пока ты сам(а) не откроешь их конкретному человеку на выбранный срок.','Nobody sees these sections until you share them with a specific person for a set time.')}</p>
 <div class="card list">${[['info','spark','l',L('Желания и границы','Wishes and limits'),L(`${S.me.jars.filter(j=>j.vis==='granted').length} тем с видимостью «по доступу»`,`${S.me.jars.filter(j=>j.vis==='granted').length} topics set to “by access”`)],['photos','image','v',L('Приватные фото','Private photos'),L('3 фото','3 photos')],['video','video','a',L('Видео','Video'),L('Пусто','Empty')],['album','book','s',L('Альбом «Лето»','Album “Summer”'),L('6 фото · новые добавления — отдельным решением','6 photos · new additions need a new decision')]].map(([k,i,t,b,s])=>linkRow({act:'p4sec',v:k,icon:i,tone:t,title:b,sub:s})).join('')}</div>
 <div class="sec">${L('Кто может запрашивать доступ','Who can request access')}</div>
 ${[['all',L('Все участники','All members')],['matches',L('Только совпадения','Matches only')],['none',L('Никто','Nobody')]].map(([k,l])=>`<button class="radio ${S.me.requestsFrom===k?'on':''}" data-act="reqFrom" data-v="${k}"><i></i><span class="tx">${l}</span></button>`).join('')}
 <p class="note mt12">${L('Выключение запросов не отзывает уже выданные доступы. Управлять ими — в «Я → Доступы».','Turning requests off doesn’t revoke access already shared. Manage it in Me → Access.')}</p></div></div>`};
ACT.p4sec=a=>{if(a.dataset.v==='info')return tab('me',{sub:'map'});ACT.phAdd&&toast(L('Раздел открывается в редакторе медиа — макет в следующей версии','This section opens in the media editor — designed in the next version'),{type:'info'});};
ACT.reqFrom=a=>run(null,()=>{S.me.requestsFrom=a.dataset.v;refresh();},{ms:300,ok:L('Сохранено','Saved')});

/* Q01 — partner link */
ACT.pairLink=()=>{sheet(()=>({title:L('Профиль пары','Couple profile'),lead:`<span class="ico v">${I.couple}</span>`,body:`<p class="lead">${L('Пара — это общий профиль двух отдельных аккаунтов. Личные карты, дневники и чаты остаются у каждого свои.','A couple is a shared profile of two separate accounts. Personal maps, journals and chats stay separate.')}</p>
 <div class="fact"><i class="g">${I.check}</i><span>${L('Общими станут: описание пары, правила и совместные публикации','Shared: couple description, rules and joint posts')}</span></div><div class="fact"><i class="g">${I.check}</i><span>${L('Совместные фото и доступы — только с согласия обоих','Joint photos and access — only with both agreeing')}</span></div>
 <label class="field mt16"><span>${L('Ник партнёра','Partner’s nickname')}</span><div class="inwrap">${I.at}<input class="inp" id="pairNick" placeholder="kira" autocapitalize="off"></div></label>`,foot:`<button class="btn primary" data-act="pairSend">${L('Отправить приглашение','Send invitation')}</button>`}));};
ACT.pairSend=a=>{const v=$('#pairNick').value.trim().toLowerCase();if(!v){$('#pairNick').classList.add('err');toast(L('Укажи ник партнёра','Enter your partner’s nickname'),{type:'err'});return;}if(!PEOPLE[v]){$('#pairNick').classList.add('err');toast(L('Такого ника нет. Проверь написание','No such nickname. Check the spelling'),{type:'err'});return;}run(a,()=>{S.pairInvite={p:v,t:Date.now()};closeSheet();refresh();},{ok:L(`Приглашение отправлено ${pname(v)}. Пара появится после её/его согласия`,`Invitation sent to ${pname(v)}. The couple appears once they accept`)});};

ACT.previewDraft=()=>{const r=cur();const value={...S.me,name:fv('name'),nick:fv('nick'),bio:{ru:fv('bio'),en:fv('bio')},city:r.f.city||null,photos:[...r.photos],photo:r.photos[0]||null,pron:r.pron,gender:[...r.gender],orient:[...r.orient],format:r.format,role:r.role,langs:[...r.langs],vis:{...r.vis}};go('P03',{preview:value},{keepDraft:true});};